import type { AudioSource } from 'expo-audio';

/**
 * Narration recorded ahead of time, by clip key.
 *
 * Generated by `node scripts/voice.mjs build`. Empty until that has been run — which it has not
 * been, so every narrated session is currently silent.
 *
 * A block with no clip is silent, not spoken by the device. There is deliberately no fallback
 * to the speech synthesiser: it is the robotic voice this exists to replace, and the text is on
 * screen either way.
 *
 * Metro resolves require() at build time, so this map cannot be built at runtime from a
 * directory listing — the script writes the requires out.
 */
export const NARRATION_AUDIO: Record<string, AudioSource> = {};
